function PTVC_ExtRegister()
	local i = 1
	while PTVC_REG[i] do
		ReLoadScript(PTVC_REG[i])
		i = i + 1
	end
	i = 1
	while PTVC_PAK[i] do
		call(ReLoadScript, { PTVC_PAK[i] }, "x", PTVC_ExtNop)
		i = i + 1
	end
	PTVC_REGISTERED = 1
end

function PTVC_ExtSpawn(tpl, lv, m, x, y, rem)
	local sw = SubWorldID2Idx(m)
	if sw == nil or sw < 0 then return 0 end
	local ni = AddNpc(tpl, lv, sw, x * 32, y * 32, rem)
	if ni == nil or ni <= 0 then ni = AddNpc(tpl, lv, sw, (x + 2) * 32, y * 32, rem) end
	if ni == nil or ni <= 0 then ni = AddNpc(tpl, lv, sw, x * 32, (y + 2) * 32, rem) end
	if ni == nil or ni <= 0 then return 0 end
	return ni
end

function PTVC_ExtNpcs()
	local k = 1
	while PTVC_NPCS[k] do
		local s = PTVC_NPCS[k]
		local ni = PTVC_NPC_IDX[k]
		if not (ni and ni > 0 and GetNpcName(ni) == s[5]) then
			ni = PTVC_ExtSpawn(s[2], 1, s[1], s[3], s[4], 0)
			if ni > 0 then
				SetNpcName(ni, s[5])
				SetNpcScript(ni, s[6])
				PTVC_NPC_IDX[k] = ni
			end
		end
		k = k + 1
	end
end

-- one scan of the NPC table: placeholders of 1071 at the authored cells (+-3) get vc_info.lua
function PTVC_ExtAdopt()
	local got = 0
	local i = 1
	while i < PTVC_MAX_NPC do
		local nm = GetNpcName(i)
		if nm and nm ~= "" and NpcIdx2PIdx(i) <= 0 then
			local w, x, y = GetNpcPos(i)
			if w == PTVC_MAP then
				local k = 1
				while PTVC_PH[k] do
					local p = PTVC_PH[k]
					if abs(x - p[1]) <= 3 and abs(y - p[2]) <= 3 and nm ~= p[3] and GetNpcParam(i, 1) ~= PTVC_K then
						SetNpcName(i, p[3])
						SetNpcScript(i, "\\script\\phongthan\\vienco\\vc_info.lua")
						got = got + 1
					elseif nm == p[3] then
						got = got + 1
					end
					k = k + 1
				end
			end
		end
		i = i + 1
	end
	PTVC_ADOPTED = got
	return got
end

function PTVC_ArmyOne(k)
	local a = PTVC_ARMY[k]
	local t = PTVC_AK[a[1] * 10 + a[2]]
	local ni = PTVC_ArmyIdx(k)
	if ni > 0 then return ni end
	ni = PTVC_ExtSpawn(t[1], t[2], PTVC_MAP, a[3], a[4], 1)
	if ni > 0 then
		SetNpcName(ni, t[3])
		SetNpcScript(ni, "\\script\\phongthan\\vienco\\vc_mob.lua")
		SetNpcCurCamp(ni, a[1])
		SetNpcParam(ni, 1, PTVC_K)
		SetNpcParam(ni, 2, a[2])
		SetNpcParam(ni, 3, a[1])
		PTVC_ARMY_IDX[k] = ni
	end
	return ni
end

-- index of army k when still ours, else 0
function PTVC_ArmyIdx(k)
	local ni = PTVC_ARMY_IDX[k]
	if ni and ni > 0 and GetNpcParam(ni, 1) == PTVC_K and GetNpcParam(ni, 2) == PTVC_ARMY[k][2] and GetNpcName(ni) == PTVC_AK[PTVC_ARMY[k][1] * 10 + PTVC_ARMY[k][2]][3] then
		return ni
	end
	return 0
end

function PTVC_ArmyEnsure()
	local k = 1
	while PTVC_ARMY[k] do
		PTVC_ArmyOne(k)
		k = k + 1
	end
end

function PTVC_ArmyClear()
	local k = 1
	while PTVC_ARMY[k] do
		local ni = PTVC_ArmyIdx(k)
		if ni > 0 then
			SetNpcParam(ni, 1, 0)
			DelNpc(ni)
		end
		PTVC_ARMY_IDX[k] = nil
		k = k + 1
	end
end

function PTVC_OpenRound(key, endmin)
	if PTVC_Open() then PTVC_Settle() end
	SetGlobalValue(PTVC_GV_ROUND, key)
	SetGlobalValue(PTVC_GV_SCORE + 1, 0)
	SetGlobalValue(PTVC_GV_SCORE + 2, 0)
	SetGlobalValue(PTVC_GV_END, endmin)
	local i = 1
	while i <= PTVC_SLOTS do
		SetGlobalValue(PTVC_GV_SLOT + i, 0)
		i = i + 1
	end
	SetGlobalValue(PTVC_GV_STATE, 2)
	PTVC_ArmyEnsure()
	AddGlobalCountNews("<color=green>Chi\213n tr\173\234ng Th\173\172ng Chu<color> (Vi\212n C\230 chi\213n tr\173\234ng) \174\183 khai chi\213n! Anh h\239ng c\202p 50 tr\235 l\170n h\183y \174\213n <color=green>Phong Th\199n \167\181i<color> g\198p Vi\212n C\230 Chi\213n S\248.", 2)
end

-- walk the participant slots: fn(slot, playerindex) runs with PlayerIndex set; stale slots are cleared
function PTVC_EachPlayer(fn)
	local old = PlayerIndex
	local key = PTVC_Round()
	local i = 1
	while i <= PTVC_SLOTS do
		local p = GetGlobalValue(PTVC_GV_SLOT + i)
		if p > 0 then
			if GetPlayerID(p) == nil then
				SetGlobalValue(PTVC_GV_SLOT + i, 0)
			else
				PlayerIndex = p
				if GetTask(PTVC_T_ROUND) ~= key or GetTask(PTVC_T_SIDE) <= 0 then
					SetGlobalValue(PTVC_GV_SLOT + i, 0)
				else
					fn(i, p)
				end
			end
		end
		i = i + 1
	end
	PlayerIndex = old
end

function PTVC_KeepOne(i, p)
	local w = GetWorldPos()
	local s = GetTask(PTVC_T_SIDE)
	if w ~= PTVC_MAP then
		-- left the battlefield (scroll, death outside...): camp back, may re-enter this round for free
		PTVC_Restore(0)
		SetGlobalValue(PTVC_GV_SLOT + i, 0)
		return
	end
	SetCurCamp(s)
	if mod(PTVC_TICKS, 10) == 0 then Msg2Player(PTVC_StatusText()) end
end

function PTVC_BattleMinute()
	PTVC_AddScore(1, random(1, 3))
	PTVC_AddScore(2, random(1, 3))
	PTVC_ArmyEnsure()
	PTVC_EachPlayer(PTVC_KeepOne)
end

function PTVC_SettleOne(i, p)
	-- 2026-10-04 (vtcc, "qua chuan VNG"): VNG <<d4b6><b9c5><d5bd><b3a1>.lua> BonusTime gives no exp / item at the end of the battle
	-- (the old level x cong trang x 30 exp was not VNG); it only adds the round score to the total (task 426),
	-- sets the Vi Quoc Lap Cong result (PTVC_Result) and sends everybody back to Phong Than Dai.
	local w = PTVC_WINNER
	local s = GetTask(PTVC_T_SIDE)
	local m = GetTask(PTVC_T_MISSION)
	local st = PTVC_Result(s == w and w > 0)
	if st == 2 then
		Msg2Player("Phe ng\173\172i th\190ng, ho\181n th\181nh 'V\222 Qu\232c L\203p C\171ng'! H\183y v\210 Phong Th\199n \167\181i g\198p Vi\212n C\230 Chi\213n S\248 nh\203n th\173\235ng.")
	elseif st == 1 then
		Msg2Player("\167\183 ho\181n th\181nh 'V\222 Qu\232c L\203p C\171ng' nh\173ng phe ng\173\172i kh\171ng th\190ng: v\210 Phong Th\199n \167\181i g\198p Vi\212n C\230 Chi\213n S\248 nh\203n th\173\235ng (\221t h\172n phe th\190ng).")
	elseif m >= 1000 then
		Msg2Player("Nhi\214m v\244 'V\222 Qu\232c L\203p C\171ng' ch\173a ho\181n th\181nh, \174\183 b\222 h\241y.")
	end
	if GetTask(PTVC_T_SCORE) > PTVC_BEST_SC then
		PTVC_BEST_SC = GetTask(PTVC_T_SCORE)
		PTVC_BEST = GetName()
	end
	Msg2Player(format("Chi\213n s\249 k\213t th\243c. C\171ng tr\185ng tr\203n n\181y: %d.", GetTask(PTVC_T_SCORE)))
	SetTask(PTVC_T_TOTAL, GetTask(PTVC_T_TOTAL) + GetTask(PTVC_T_SCORE))
	SetTask(PTVC_T_SCORE, 0)
	SetTask(PTVC_T_SIDE, 0)
	if GetWorldPos() == PTVC_MAP then
		PTVC_Restore(1)
	else
		PTVC_Restore(0)
	end
	SetGlobalValue(PTVC_GV_SLOT + i, 0)
end

function PTVC_Settle()
	local a = PTVC_Score(1)
	local b = PTVC_Score(2)
	PTVC_WINNER = 0
	if a > b then PTVC_WINNER = 1 elseif b > a then PTVC_WINNER = 2 end
	PTVC_BEST = ""
	PTVC_BEST_SC = 0
	SetGlobalValue(PTVC_GV_LAST, PTVC_Round())
	SetGlobalValue(PTVC_GV_WIN, PTVC_WINNER)
	PTVC_EachPlayer(PTVC_SettleOne)
	SetGlobalValue(PTVC_GV_STATE, 0)
	PTVC_ArmyClear()
	local t = format("<color=green>Chi\213n tr\173\234ng Th\173\172ng Chu<color> k\213t th\243c: phe Th\173\172ng %d - phe Chu %d. ", a, b)
	if PTVC_WINNER == 0 then
		t = t .. "B\202t ph\169n th\190ng b\185i."
	else
		t = t .. PTVC_SIDENAME[PTVC_WINNER] .. " th\190ng l\238i v\206 vang!"
	end
	if PTVC_BEST ~= "" then t = t .. " D\242ng s\220 \174\214 nh\202t: <color=green>" .. PTVC_BEST .. "<color>." end
	AddGlobalCountNews(t, 2)
end

function PTVC_Schedule()
	local h = tonumber(date("%H")) or 0
	local m = tonumber(date("%M")) or 0
	local now = h * 60 + m
	-- 2026-10-04 (agent vtcc): a round opened by the Lenh Bai Chien Truong Thuong Chu (item state, GlobalValues
	-- only, thuongchu_lenhbai.lua) is adopted as a forced round: armies now, settled at its own end minute.
	local rq = GetGlobalValue(PTVC_GV_REQ)
	if rq ~= 0 then
		SetGlobalValue(PTVC_GV_REQ, 0)
		if PTVC_Open() and PTVC_Round() == rq then
			PTVC_FORCE_END = PTVC_TICKS + PTVC_MinLeft()
		end
	end
	if PTVC_FORCE_END and PTVC_FORCE_END > 0 then
		if PTVC_TICKS < PTVC_FORCE_END then
			PTVC_BattleMinute()
			return
		end
		PTVC_FORCE_END = 0
		if PTVC_Open() then PTVC_Settle() end
		return
	end
	if PTVC_HOURS[h] == 1 and m < PTVC_LEN then
		local key = tonumber(date("%m%d%H")) * 100
		if not PTVC_Open() or PTVC_Round() ~= key then
			PTVC_OpenRound(key, h * 60 + PTVC_LEN)
		end
		PTVC_BattleMinute()
	elseif PTVC_Open() then
		PTVC_Settle()
	end
end

-- admin / test helper (bridge): open a round now for PTVC_LEN minutes
function PTVC_ForceOpen()
	local h = tonumber(date("%H")) or 0
	local m = tonumber(date("%M")) or 0
	PTVC_FORCE_END = PTVC_TICKS + PTVC_LEN
	PTVC_OpenRound(tonumber(date("%m%d%H%M")), mod(h * 60 + m + PTVC_LEN, 1440))
	return PTVC_Round()
end

function PTEXT_vienco_Tick()
	PTVC_TICKS = PTVC_TICKS + 1
	if not PTVC_REGISTERED then PTVC_ExtRegister() end
	PTVC_ExtNpcs()
	if PTVC_ADOPTED == nil or (PTVC_ADOPTED < 5 and mod(PTVC_TICKS, 60) == 0) then PTVC_ExtAdopt() end
	PTVC_Schedule()
end
